package main

import "fmt"

func change(val int) {
  val = 8
}
// 参数ptr 为int类型指针
func change_ptr(ptr *int) {
  *ptr = 8
}

func main() {
  x := 42

  change(x)
  fmt.Println(x)

  change_ptr(&x)
  fmt.Println(x)
}

